async function through(response, payload) {
  const data = await (await kakaoGroupCompatibleResponse(response, payload, BASE)).json();
  const outputs = data?.template?.outputs || [];
  return { outputs, texts: outputs.map(bubbleText), text: outputs.map(bubbleText).join("\n----\n"), quickReplies: data?.template?.quickReplies || [] };
}
