  const memberIds = new Set(fx.db.household_members.filter((member) => member.household_id === household).map((member) => member.user_id));
  const linesOf = (reply) => ({ person: reply.lines.filter((line) => /^• [^→]+: .+ → .+$/.test(line)), transfer: reply.lines.filter((line) => /^• .+ → .+: [\d,]+원$/.test(line)) });
  const outside = (reply, pattern) => Number((reply.text.match(pattern) || [])[1] || 0);
  // 이름 길이를 늘려 가며 본다: 줄 수가 줄어도 ‘외 N명·외 N건’ 이 맞고, 두 묶음이 같은 줄 수로 줄고, 환급 안내는 끝에 남는다.
