    const { person, transfer } = linesOf(reply);
    seen.add(person.length);
    check(() => ok(reply.text.length <= 950 && reply.bubbles.length === 1 && reply.lines.at(-1) === `※ ${NOTICE}`, `S-1 이름 ${length}자: 950자 안이고 환급 안내가 끝에 있다(${reply.text.length}자)`), `long ${length} notice`);
    check(() => eq(person.length + outside(reply, /외 (\d+)명은 웹 정산 화면에서/), 10, `S-1 이름 ${length}자: 보이는 사람 줄 + ‘외 N명’ = 10명(${person.length}줄)`), `long ${length} people count`);
    check(() => eq(transfer.length + outside(reply, /외 (\d+)건은 웹 정산 화면에서/), 9, `S-1 이름 ${length}자: 보이는 송금 줄 + ‘외 N건’ = 9건(${transfer.length}줄)`), `long ${length} transfer count`);
    check(() => ok(person.length >= 3 && person.length <= 8 && transfer.length === Math.min(person.length, 9), `S-1 이름 ${length}자: 두 묶음이 같은 줄 수로 줄어든다(사람 ${person.length} · 송금 ${transfer.length})`), `long ${length} same shown`);
    // 줄 수는 꼭 필요한 만큼만 줄인다: 한 줄을 더 보이면 한도(930자)를 넘는다.
